"""Builds the generated files in kindle/kindledash/:

  fonts/{R,S,B,D}.ttf  static, Latin-subset font instances (FBInk's stb_truetype can't use variable fonts)
  fontdata.awk         font metrics and glyph advance widths, so render.awk can measure text
  icons/*.png          weather icons, small detail icons, rounded-corner pieces (16 gray levels)

Run from the repo root:  uv run --project tools python tools/build.py
Font set: KD_FONTS=nunito (default) or KD_FONTS=fredoka (Fredoka for the large display text).
"""

from __future__ import annotations

import os
import shutil
import sys
from pathlib import Path

from fontTools import subset
from fontTools.ttLib import TTFont
from fontTools.varLib import instancer

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "tools" / "fonts-src"
OUT = ROOT / "kindle" / "kindledash"

sys.path.insert(0, str(ROOT / "tools"))
import icons  # noqa: E402

# Roles used by render.awk: R text, S semibold text, B bold text and titles, D display (big sizes)
NUNITO = {
    "R": ("Nunito-Variable.ttf", {"wght": 500}),
    "S": ("Nunito-Variable.ttf", {"wght": 700}),
    "B": ("Nunito-Variable.ttf", {"wght": 800}),
    "D": ("Nunito-Variable.ttf", {"wght": 900}),
}
FONT_SETS = {
    "nunito": NUNITO,
    "fredoka": {**NUNITO, "D": ("Fredoka-Variable.ttf", {"wght": 600, "wdth": 100})},
}
LICENSES = {"Nunito-Variable.ttf": "Nunito-OFL.txt", "Fredoka-Variable.ttf": "Fredoka-OFL.txt"}

# Latin, Latin-1 Supplement, Latin Extended-A, general punctuation, degree, minus, euro, arrows
UNICODES = (
    list(range(0x20, 0x7F)) + list(range(0xA0, 0x180)) + list(range(0x2010, 0x2028))
    + list(range(0x2030, 0x203B)) + [0x2044, 0x20AC, 0x2122, 0x2190, 0x2191, 0x2192, 0x2193, 0x2212]
)

KINDS = ("clear", "partly", "cloudy", "fog", "drizzle", "rain", "snow", "storm")
CARD = 238  # GRAYE, the card background
GRAYS = {"e": 238, "d": 221, "0": 0}


def build_fonts(fonts: dict) -> list[str]:
    d = OUT / "fonts"
    shutil.rmtree(d, ignore_errors=True)
    d.mkdir(parents=True)
    lines = [
        "# Generated by tools/build.py. Do not edit.",
        "# FA/FD = hhea ascent/descent, FU = units per em, W[font, char] = advance width in font units.",
        "BEGIN {",
    ]
    for key, (src, axes) in fonts.items():
        font = instancer.instantiateVariableFont(TTFont(SRC / src), axes)
        opts = subset.Options()
        opts.layout_features = ["kern", "liga", "calt", "tnum", "case"]
        opts.name_IDs = ["*"]
        opts.notdef_outline = True
        sub = subset.Subsetter(opts)
        sub.populate(unicodes=UNICODES)
        sub.subset(font)
        path = d / f"{key}.ttf"
        font.save(path)
        shutil.copy(SRC / LICENSES[src], d / LICENSES[src])

        hhea, upem = font["hhea"], font["head"].unitsPerEm
        cmap, hmtx = font.getBestCmap(), font["hmtx"]
        lines.append(f'  FA["{key}"] = {hhea.ascent}; FD["{key}"] = {hhea.descent}; FU["{key}"] = {upem}')
        for cp in sorted(cmap):
            ch = chr(cp)
            if ch in '"\\':
                ch = "\\" + ch
            lines.append(f'  W["{key}", "{ch}"] = {hmtx[cmap[cp]][0]}')
        print(f"font {key}: {src} {axes}, {path.stat().st_size // 1024} KB, {len(cmap)} glyphs")
    lines.append("}")
    return lines


def save(img, name: str) -> None:
    img.point(lambda v: round(v / 17) * 17).save(OUT / "icons" / name, optimize=True)


def build_icons() -> None:
    d = OUT / "icons"
    shutil.rmtree(d, ignore_errors=True)
    d.mkdir(parents=True)
    for kind in KINDS:
        for dn, is_day in (("d", True), ("n", False)):
            save(icons.icon(kind, 170, is_day, CARD), f"{kind}-{dn}-170.png")  # current weather, on the card
            save(icons.icon(kind, 56, is_day), f"{kind}-{dn}-56.png")          # hourly and daily rows
    for kind in ("humidity", "umbrella", "wind", "sunrise", "sunset"):
        save(icons.mini(kind, 30, CARD), f"mini-{kind}-30.png")
    save(icons.mini("drop", 16), "mini-drop-16.png")
    for r, col in ((18, "e"), (14, "0"), (14, "d")):
        for q in ("tl", "tr", "bl", "br"):
            save(icons.corner(r, GRAYS[col], q), f"corner-{r}-{col}-{q}.png")
    print(f"icons: {len(list(d.iterdir()))} PNGs")


if __name__ == "__main__":
    name = os.environ.get("KD_FONTS", "nunito")
    data = build_fonts(FONT_SETS[name])
    (OUT / "fontdata.awk").write_text("\n".join(data) + "\n", encoding="utf-8")
    build_icons()
